import{_ as l,a0 as p,w as r,s as o,I as e,x as t,a1 as i,A as n,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"在 Linux 上创建一个加密文件保险库 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上创建一个加密文件保险库 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上创建一个加密文件保险库 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上创建一个加密文件保险库 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210413 Create an encrypted file vault on Linux","title":"在 Linux 上创建一个加密文件保险库","tag":"202104","desc":""},"relativePath":"202104/20210413 Create an encrypted file vault on Linux.md","filePath":"[post].md"}'),d={name:"202104/20210413 Create an encrypted file vault on Linux.md"};function h(g,s,k,m,b,f){const a=p("Link");return r(),o("div",null,[s[29]||(s[29]=e("h1",{id:"在-linux-上创建一个加密文件保险库",tabindex:"-1"},[t("在 Linux 上创建一个加密文件保险库 "),e("a",{class:"header-anchor",href:"#在-linux-上创建一个加密文件保险库","aria-label":"Permalink to “在 Linux 上创建一个加密文件保险库”"},"​")],-1)),s[30]||(s[30]=e("blockquote",null,[e("p",null,"使用 Linux 统一密钥设置（LUKS）为物理驱动器或云存储上的敏感文件创建一个加密保险库。")],-1)),s[31]||(s[31]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/14/151220l5zkkxiukgzix54k.jpg",alt:""})],-1)),e("p",null,[s[3]||(s[3]=t("最近，我演示了如何在 Linux 上使用",-1)),s[4]||(s[4]=e("ruby",null,[t("统一密钥设置"),e("rt",null,"Linux Unified Key Setup")],-1)),s[5]||(s[5]=t("（",-1)),i(a,{href:"https://gitlab.com/cryptsetup/cryptsetup/blob/master/README.md"},{default:n(()=>[...s[0]||(s[0]=[t("LUKS",-1)])]),_:1}),s[6]||(s[6]=t("）和 ",-1)),s[7]||(s[7]=e("code",null,"cryptsetup",-1)),s[8]||(s[8]=t(" 命令 ",-1)),i(a,{href:"https://opensource.com/article/21/3/encryption-luks"},{default:n(()=>[...s[1]||(s[1]=[t("实现全盘加密",-1)])]),_:1}),s[9]||(s[9]=t("。虽然加密整个硬盘在很多情况下是有用的，但也有一些原因让你不想对整个硬盘进行加密。例如，你可能需要让一个硬盘在多个平台上工作，其中一些平台可能没有集成 ",-1)),i(a,{href:"https://gitlab.com/cryptsetup/cryptsetup/blob/master/README.md"},{default:n(()=>[...s[2]||(s[2]=[t("LUKS",-1)])]),_:1}),s[10]||(s[10]=t("。此外，现在是 21 世纪，由于云的存在，你可能不会使用物理硬盘来处理所有的数据。",-1))]),e("p",null,[s[12]||(s[12]=t("几年前，有一个名为 ",-1)),i(a,{href:"https://en.wikipedia.org/wiki/TrueCrypt"},{default:n(()=>[...s[11]||(s[11]=[t("TrueCrypt",-1)])]),_:1}),s[13]||(s[13]=t(" 的系统，允许用户创建加密的文件保险库，可以通过 TrueCrypt 解密来提供读/写访问。这是一项有用的技术，基本上提供了一个虚拟的便携式、完全加密的驱动器，你可以在那里存储重要数据。TrueCrypt 项目关闭了，但它可以作为一个有趣的模型。",-1))]),s[32]||(s[32]=u(`<p>幸运的是，LUKS 是一个灵活的系统，你可以使用它和 <code>cryptsetup</code> 在一个独立的文件中创建一个加密保险库，你可以将其保存在物理驱动器或云存储中。</p><p>下面就来介绍一下怎么做。</p><h3 id="_1、建立一个空文件" tabindex="-1">1、建立一个空文件 <a class="header-anchor" href="#_1、建立一个空文件" aria-label="Permalink to “1、建立一个空文件”">​</a></h3><p>首先，你必须创建一个预定大小的空文件。就像是一种保险库或保险箱，你可以在其中存储其他文件。你使用的命令是 <code>util-linux</code> 软件包中的 <code>fallocate</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fallocate --length 512M vaultfile.img</span></span></code></pre></div><p>这个例子创建了一个 512MB 的文件，但你可以把你的文件做成任何你想要的大小。</p><h3 id="_2、创建一个-luks-卷" tabindex="-1">2、创建一个 LUKS 卷 <a class="header-anchor" href="#_2、创建一个-luks-卷" aria-label="Permalink to “2、创建一个 LUKS 卷”">​</a></h3><p>接下来，在空文件中创建一个 LUKS 卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cryptsetup --verify-passphrase \\</span></span>
<span class="line"><span>    luksFormat vaultfile.img</span></span></code></pre></div><h3 id="_3、打开-luks-卷" tabindex="-1">3、打开 LUKS 卷 <a class="header-anchor" href="#_3、打开-luks-卷" aria-label="Permalink to “3、打开 LUKS 卷”">​</a></h3><p>要想创建一个可以存储文件的文件系统，必须先打开 LUKS 卷，并将其挂载到电脑上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cryptsetup open \\</span></span>
<span class="line"><span>    --type luks vaultfile.img myvault</span></span>
<span class="line"><span>$ ls /dev/mapper</span></span>
<span class="line"><span>myvault</span></span></code></pre></div><h3 id="_4、建立一个文件系统" tabindex="-1">4、建立一个文件系统 <a class="header-anchor" href="#_4、建立一个文件系统" aria-label="Permalink to “4、建立一个文件系统”">​</a></h3><p>在你打开的保险库中建立一个文件系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkfs.ext4 -L myvault /dev/mapper/myvault</span></span></code></pre></div><p>如果你现在不需要它做什么，你可以关闭它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cryptsetup close myvault</span></span></code></pre></div><h3 id="_5、开始使用你的加密保险库" tabindex="-1">5、开始使用你的加密保险库 <a class="header-anchor" href="#_5、开始使用你的加密保险库" aria-label="Permalink to “5、开始使用你的加密保险库”">​</a></h3><p>现在一切都设置好了，你可以在任何需要存储或访问私人数据的时候使用你的加密文件库。要访问你的保险库，必须将其挂载为一个可用的文件系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cryptsetup open \\</span></span>
<span class="line"><span>    --type luks vaultfile.img myvault</span></span>
<span class="line"><span>$ ls /dev/mapper</span></span>
<span class="line"><span>myvault</span></span>
<span class="line"><span>$ sudo mkdir /myvault</span></span>
<span class="line"><span>$ sudo mount /dev/mapper/myvault /myvault</span></span></code></pre></div><p>这个例子用 <code>cryptsetup</code> 打开保险库，然后把保险库从 <code>/dev/mapper</code> 下挂载到一个叫 <code>/myvault</code> 的新目录。和 Linux 上的任何卷一样，你可以把 LUKS 卷挂载到任何你想挂载的地方，所以除了 <code>/myvault</code>，你可以用 <code>/mnt</code> 或 <code>~/myvault</code> 或任何你喜欢的位置。</p><p>当它被挂载后，你的 LUKS 卷就会被解密。你可以像读取和写入文件一样读取和写入它，就像它是一个物理驱动器一样。</p><p>当使用完你的加密保险库时，请卸载并关闭它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo umount /myvault</span></span>
<span class="line"><span>$ sudo cryptsetup close myvault</span></span></code></pre></div><h3 id="加密的文件保险库" tabindex="-1">加密的文件保险库 <a class="header-anchor" href="#加密的文件保险库" aria-label="Permalink to “加密的文件保险库”">​</a></h3><p>你用 LUKS 加密的镜像文件和其他文件一样，都是可移动的，因此你可以将你的保险库存储在硬盘、外置硬盘，甚至是互联网上。只要你可以使用 LUKS，就可以解密、挂载和使用它来保证你的数据安全。轻松加密，提高数据安全性，不妨一试。</p><hr>`,27)),e("p",null,[s[15]||(s[15]=t("via: ",-1)),i(a,{href:"https://opensource.com/article/21/4/linux-encryption"},{default:n(()=>[...s[14]||(s[14]=[t("https://opensource.com/article/21/4/linux-encryption",-1)])]),_:1})]),e("p",null,[s[20]||(s[20]=t("作者：",-1)),i(a,{href:"https://opensource.com/users/seth"},{default:n(()=>[...s[16]||(s[16]=[t("Seth Kenlon",-1)])]),_:1}),s[21]||(s[21]=t(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[17]||(s[17]=[t("lujun9972",-1)])]),_:1}),s[22]||(s[22]=t(" 译者：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[18]||(s[18]=[t("wxy",-1)])]),_:1}),s[23]||(s[23]=t(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[19]||(s[19]=[t("wxy",-1)])]),_:1})]),e("p",null,[s[26]||(s[26]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[24]||(s[24]=[t("LCTT",-1)])]),_:1}),s[27]||(s[27]=t(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[25]||(s[25]=[t("Linux中国",-1)])]),_:1}),s[28]||(s[28]=t(" 荣誉推出",-1))])])}const L=l(d,[["render",h]]);export{v as __pageData,L as default};
